#include <iostream>
using namespace std;

enum class MENU{
  Espresso = 1,
  Americano=2,
  SugarCoffee=3,
  Fill=5
};

class CoffeeMachine{
  int coffee, water, sugar;
public:
  CoffeeMachine(int c, int w, int s);
  void drinkEspresso();
  void drinkAmericano();
  void drinkSugarCoffee();
  void fill();
  void show() const;
};

CoffeeMachine::CoffeeMachine(int coffee, int water, int sugar) : coffee{coffee}, water{water}, sugar{sugar}{}

void CoffeeMachine::drinkEspresso(){
  if (coffee < 1 || water < 1)
    return;

  coffee--;
  water--;
}
void CoffeeMachine::drinkAmericano(){
  if (coffee < 1 || water < 2)
    return;


  coffee--;
  water -= 2;
}
void CoffeeMachine::drinkSugarCoffee(){
  if (coffee < 1 || water < 2 || sugar < 1)
    return;

  coffee--;
  water -= 2;
  sugar-=2;
}
void CoffeeMachine::fill(){
  if (coffee < 5) {
    cout<<"coffee를 "<<10-coffee<<"g 보충"<<endl;
    coffee += (10 - coffee);
  }
  if (water < 5) {
    cout<<"water를 "<<10-water<<"리터 보충"<<endl;
    water += (10 - water);
  }
  if (sugar < 5) {
    cout<<"sugar를 "<<10-sugar<<"g 보충"<<endl;
    sugar += (10 - sugar);
  }
}

void CoffeeMachine::show() const{
  cout << "커피 머신 상태, 커피:" << coffee << "\t";
  cout << "물:" << water << "\t";
  cout << "설탕:" << sugar << "\t" << endl;
}

int main(){
  int menu;
  CoffeeMachine java{10, 10, 10}; // 커피량:10, 물량:10, 설탕:10으로 초기화

  while (true) {
    cout << "커피 종류 선택 : Espresso = 1, Americano=2, SugarCoffee=3, Exit=4, Fill=5 >> ";
    cin >> menu;
    cout<<menu<<endl;

    if (menu == 4) {
      break;
    }

    switch (static_cast<MENU>(menu))    {
    case MENU::Espresso:
      java.drinkEspresso(); // 커피 1, 물 1 소비
      break;
    case MENU::Americano:
      java.drinkAmericano(); // 커피 1, 물 2 소비
      break;
    case MENU::SugarCoffee:
      java.drinkSugarCoffee(); // 커피 1, 물 2, 설탕 2 소비
      break;
    case MENU::Fill:
      java.fill(); // 현재 머신에 남아 있는 커피와 물, 설탕 수량이 5미만이면 최대 용량으로 채워 넣기
      break;
    default:
      cout << "메뉴 없음"<<endl;
    }
    java.show(); // 현재 커피 머신의 상태 출력
  }
  cout<<"커피 머신을 종료합니다"<<endl;
  return 0;
}

