#include <iostream>
using namespace std;

class CoffeeMachine {
private:
    int coffee;
    int water;
    int sugar;

public:
    CoffeeMachine(int c, int w, int s);
    void drinkEspresso();
    void drinkAmericano();
    void drinkSugarCoffee();
    void fill();
    void show() const;
};

// 생성자 (소괄호 초기화 리스트 사용)
CoffeeMachine::CoffeeMachine(int c, int w, int s) : coffee(c), water(w), sugar(s) {}

void CoffeeMachine::drinkEspresso() {
    if (coffee >= 1 && water >= 1) {
        coffee -= 1;
        water -= 1;
    }
}

void CoffeeMachine::drinkAmericano() {
    if (coffee >= 1 && water >= 2) {
        coffee -= 1;
        water -= 2;
    }
}

void CoffeeMachine::drinkSugarCoffee() {
    if (coffee >= 1 && water >= 2 && sugar >= 2) {
        coffee -= 1;
        water -= 2;
        sugar -= 2;
    }
}

void CoffeeMachine::fill() {
    if (coffee < 5) {
        int add = 10 - coffee;
        cout << "coffee를 " << add << "g 보충" << endl;
        coffee = 10;
    }
    if (water < 5) {
        int add = 10 - water;
        cout << "water를 " << add << "리터 보충" << endl;
        water = 10;
    }
    if (sugar < 5) {
        int add = 10 - sugar;
        cout << "sugar를 " << add << "g 보충" << endl;
        sugar = 10;
    }
}

void CoffeeMachine::show() const {
    cout << "커피 머신 상태, 커피:" << coffee << "\t물:" << water << "\t설탕:" << sugar << "\t" << endl;
}

int main() {
    CoffeeMachine java{10, 10, 10};
    int choice;

    while (true) {
        cout << "커피 종류 선택 : Espresso = 1, Americano=2, SugarCoffee=3, Exit=4, Fill=5 >> ";
        cin >> choice;
        cout << choice << endl;

        if (choice == 4) {
            break;
        }

        if (choice == 1) {
            java.drinkEspresso();
        } else if (choice == 2) {
            java.drinkAmericano();
        } else if (choice == 3) {
            java.drinkSugarCoffee();
        } else if (choice == 5) {
            java.fill();
        } else {
            cout << "메뉴 없음" << endl;
        }

        java.show();
    }

    cout << "커피 머신을 종료합니다" << endl;
    return 0;
}

