class ArrayUtil{
public:
  // s1과 s2를 연결한 새로운 배열을 동적 생성하여 리턴
  static int *concat(int s1[], int size1, int s2[], int size2, int &retSize);

  // s1에서 s2에 있는 숫자를 모두 삭제한 새로운 배열을 동적 생성하여 리턴
  static int *remove(int s1[], int size1, int s2[], int size2, int &retSize);

  //입력 받은 크기만큼 배열을 동적 생성하여 리턴, 입력 받은 배열 크기는 count에 저장
  static int *create(int &count);

  //배열 원소 출력
  static void print(int *arr, int size);
};

void ArrayUtil::print(int *arr, int size) {
  for (int i = 0; i < size; i++)
    cout << arr[i] << ' ';
  cout << endl;
}

int *ArrayUtil::create(int& count){
  int *x = nullptr;

  while (count < 1 || count > 5){
    cout << "\nx배열의 원소(1~5)는 몇 개 ? ";
    cin >> count;
    cout << count << endl;
  }


  x = new int[count];


  cout << "x배열에 저장할 정수 입력 : ";
  for (int i = 0; i < count; i++)
    cin >> x[i];
  for (int i = 0; i < count; i++) {
    cout << x[i] << " ";
  }
  cout << endl;

  return x;
}

int *ArrayUtil::concat(int s1[], int size1, int s2[], int size2, int& retSize){
  retSize = size1 + size2;
  int *p = new int[retSize];
  if (!p)
    return nullptr;

  for (int i = 0; i < size1; i++)
    p[i] = s1[i];
  for (int i = 0; i < size2; i++)
    p[i + size1] = s2[i];
  return p;
}

int *ArrayUtil::remove(int s1[], int size1, int s2[], int size2, int& retSize){
  int *p = new int[size1];
  if (!p){
    retSize = 0;
    return nullptr;
  }

  int len = 0;
  for (int i = 0; i < size1; i++) {
    int j;
    for (j = 0; j < size2; j++){
      if (s1[i] == s2[j])
        break;
    }
    if (j == size2){
      p[len] = s1[i];
      len++;
    }
  }

  retSize = len;


  if (len == 0) {
    delete[] p;
    return nullptr;
  }

  int *q = new int[retSize];
  if (!q){
    delete[] p;
    retSize = 0;
    return nullptr;
  }

  for (int i = 0; i < retSize; i++)
    q[i] = p[i];

  delete[] p;
  return q;
}

