class Point {
	int x, y;
public:
	Point(int x, int y) {
		this->x = x; this->y = y;
	}
	int getX() { return x; }
	int getY() { return y; }
protected:
	void move_up(int x, int y) { this->x += x; this->y += y; }
	void move_down(int x, int y) { this->x -= x; this->y -= y; }
};

class ColorPoint : public Point {
	string color;
public:
	ColorPoint() : Point(0, 0) {
		this->color = "BLACK";
	}

	ColorPoint(int x, int y, string color ="BLUE") : Point(x, y) {
		this->color = color;
	}

	void setPoint(int x, int y, char op) {
		switch (op) {
		case '+' :
			move_up(x, y);
			break;
		case '-' :
			move_down(x, y);
			break;
		}
	}

	void setColor(string color) {
		this->color = color;
	}

	void show() {
		cout << color << "색으로 " << '(' << getX() << ',' << getY() << ')' << "에 위치한 점입니다." << endl;
	}
};

