	bool operation(bool x, bool y) {
		return x && y;
	}
};

class ORGate : public AbstractGate {
public:
	bool operation(bool x, bool y) {
		return x || y;
	}
};

class XORGate : public AbstractGate {
public:
	bool operation(bool x, bool y) {
		return x ^ y;
	}
};

class Manage {
public:
	static void go();
};

void Manage::go() {
	AbstractGate *ag = nullptr;

	int choice;
	bool b1, b2;

	while (true) {
		cout << "연산 종류를 선택하세요 1.and, 2.or 3.xor 4. stop>> ";
